type Package struct { ID string `json:"id"`; Name string `json:"name"`; Description string `json:"description"`; Currency string `json:"currency"`; MonthlyPrice int64 `json:"monthly_price"`; Active bool `json:"active"` }
type PackageAllowance struct { ID string `json:"id"`; PackageID string `json:"package_id"`; Metric string `json:"metric"`; IncludedQuantity int64 `json:"included_quantity"`; OverageUnitPrice int64 `json:"overage_unit_price"` }
type UsageEvent struct { ID string `json:"id"`; UserID string `json:"user_id"`; SubscriptionID string `json:"subscription_id"`; Metric string `json:"metric"`; Quantity int64 `json:"quantity"`; IdempotencyKey string `json:"idempotency_key"`; OccurredAt time.Time `json:"occurred_at"` }
func usageStatusAllowed(status string)bool{switch status{case "incomplete","active","past_due","paused":return true};return false}
func stripePriceForPackage(packageID string) string { key:=""; switch strings.TrimSpace(packageID){case "pkg_starter":key="STRIPE_PRICE_PKG_STARTER";case "pkg_creator":key="STRIPE_PRICE_PKG_CREATOR";case "pkg_pro":key="STRIPE_PRICE_PKG_PRO";case "pkg_247":key="STRIPE_PRICE_PKG_247";default: key="STRIPE_PRICE_"+strings.ToUpper(strings.NewReplacer("-","_",".","_","/","_").Replace(strings.TrimSpace(packageID)))}; return strings.TrimSpace(os.Getenv(key)) }
func registerPackageRoutes(r *gin.Engine,s *Server){api:=r.Group("/v1");api.Use(s.auth);api.GET("/packages",func(c *gin.Context){var p []Package;if err:=s.db.Table("packages").Where("active = true").Order("monthly_price asc").Find(&p).Error;err!=nil{c.JSON(500,gin.H{"error":"failed to load packages"});return};c.JSON(200,gin.H{"packages":p})});api.GET("/packages/:id/allowances",func(c *gin.Context){var a []PackageAllowance;if err:=s.db.Table("package_allowances").Where("package_id = ?",c.Param("id")).Find(&a).Error;err!=nil{c.JSON(500,gin.H{"error":"failed to load allowances"});return};c.JSON(200,gin.H{"allowances":a})});api.POST("/packages/:id/subscribe",func(c *gin.Context){uid:=c.GetString("user_id");var p Package;if err:=s.db.Table("packages").Where("id = ? AND active = true",strings.TrimSpace(c.Param("id"))).First(&p).Error;err!=nil{c.JSON(404,gin.H{"error":"package not found"});return};var existing Subscription;if err:=s.db.Where("user_id = ? AND resource_type = ? AND resource_id = ? AND package_id = ? AND status = ?",uid,"platform","channel",p.ID,"incomplete").Order("updated_at desc").First(&existing).Error;err==nil{c.JSON(200,gin.H{"subscription":existing,"idempotent":true,"payment_required":existing.GiftDiscountPercent<100});return};hasPrior,err:=firstChannelSubscriptionExists(s.db,uid);if err!=nil{c.JSON(500,gin.H{"error":"failed to check subscription eligibility"});return};var gift GiftToken;var in struct{GiftCode string `json:"giftCode"`};if err:=c.ShouldBindJSON(&in);err!=nil&&err.Error()!="EOF"{c.JSON(400,gin.H{"error":"invalid subscription request"});return};giftCode:=normalizeGiftCode(in.GiftCode);if hasPrior&&giftCode!=""{c.JSON(409,gin.H{"error":"gift codes apply only to a first channel plan subscription"});return};if giftCode!=""{loadedErr:=s.db.Where("code = ?",giftCode).First(&gift).Error;if loadedErr!=nil||!giftTokenAvailable(gift,time.Now().UTC()){c.JSON(400,gin.H{"error":"gift code is invalid, expired, or fully redeemed"});return};var redemption GiftRedemption;if err:=s.db.Where("gift_token_id = ? AND user_id = ?",gift.ID,uid).First(&redemption).Error;err==nil{c.JSON(409,gin.H{"error":"gift code has already been redeemed by this user"});return}else if !errors.Is(err,gorm.ErrRecordNotFound){c.JSON(500,gin.H{"error":"gift code could not be validated"});return}} else if !hasPrior {var ok bool;gift,ok,err=claimedGiftForUser(s.db,uid);if err!=nil{c.JSON(500,gin.H{"error":"failed to load gift claim"});return};if !ok{gift=GiftToken{}}}
	priceID:=stripePriceForPackage(p.ID);if p.MonthlyPrice>0&&priceID==""&&gift.DiscountPercent<100{c.JSON(http.StatusServiceUnavailable,gin.H{"error":"Stripe price is not configured for this package","code":"STRIPE_PRICE_NOT_CONFIGURED"});return};now:=time.Now().UTC();periodEnd:=now.AddDate(0,1,0);var giftID *string;if gift.ID!=""{id:=gift.ID;giftID=&id};sub:=Subscription{ID:newID("sub"),UserID:uid,PackageID:p.ID,ResourceType:"platform",ResourceID:"channel",PriceID:priceID,Provider:"stripe",GiftTokenID:giftID,GiftDiscountPercent:gift.DiscountPercent,Status:"incomplete",CurrentPeriodStart:now,CurrentPeriodEnd:periodEnd};if gift.DiscountPercent==100{sub.Status="active"};if err:=s.db.Transaction(func(tx *gorm.DB)error{if err:=tx.Create(&sub).Error;err!=nil{return err};if gift.DiscountPercent==100{return redeemGiftToken(tx,gift.ID,uid,sub.ID)};return nil});err!=nil{c.JSON(409,gin.H{"error":"subscription could not be created"});return};if gift.DiscountPercent<100{c.JSON(http.StatusCreated,gin.H{"subscription":sub,"payment_required":p.MonthlyPrice>0,"next":"checkout","giftDiscountPercent":gift.DiscountPercent});return};if gift.DiscountPercent==100{if err:=syncSubscriptionEntitlementState(s,sub);err!=nil{c.JSON(500,gin.H{"error":"premium access could not be activated"});return};c.JSON(http.StatusCreated,gin.H{"subscription":sub,"payment_required":false,"next":"channel","giftDiscountPercent":100});return};c.JSON(http.StatusCreated,gin.H{"subscription":sub,"payment_required":p.MonthlyPrice>0,"next":"checkout","giftDiscountPercent":gift.DiscountPercent})});api.POST("/usage",func(c *gin.Context){key:=strings.TrimSpace(c.GetHeader("Idempotency-Key"));if key==""||len(key)>128{c.JSON(400,gin.H{"error":"Idempotency-Key is required"});return};var in struct{SubscriptionID string `json:"subscription_id"`;Metric string `json:"metric"`;Quantity int64 `json:"quantity"`;OccurredAt *time.Time `json:"occurred_at"`};if err:=c.ShouldBindJSON(&in);err!=nil||strings.TrimSpace(in.SubscriptionID)==""||strings.TrimSpace(in.Metric)==""||in.Quantity<0{c.JSON(400,gin.H{"error":"invalid usage event"});return};uid:=c.GetString("user_id");subID:=strings.TrimSpace(in.SubscriptionID);metric:=strings.TrimSpace(in.Metric);at:=time.Now().UTC();if in.OccurredAt!=nil{at=in.OccurredAt.UTC()};var existing UsageEvent;if err:=s.db.Table("usage_events").Where("idempotency_key = ?",key).First(&existing).Error;err==nil{if existing.UserID!=uid{c.JSON(409,gin.H{"error":"idempotency key belongs to another user"});return};c.JSON(200,gin.H{"usage":existing,"idempotent":true});return};txErr:=s.db.Transaction(func(tx *gorm.DB)error{var sub Subscription;if err:=tx.Where("id = ? AND user_id = ?",subID,uid).Clauses(clause.Locking{Strength:"UPDATE"}).First(&sub).Error;err!=nil{return errors.New("subscription not found")};if !usageStatusAllowed(sub.Status){return errors.New("subscription is not billable")};if sub.CurrentPeriodStart.IsZero()||sub.CurrentPeriodEnd.IsZero()||!at.Before(sub.CurrentPeriodEnd)||at.Before(sub.CurrentPeriodStart){return errors.New("usage event is outside the current billing period")};var allowance PackageAllowance;if err:=tx.Table("package_allowances").Where("package_id = ? AND metric = ?",sub.PackageID,metric).First(&allowance).Error;err!=nil{return errors.New("metric is not included in subscription package")};ev:=UsageEvent{ID:newID("use"),UserID:uid,SubscriptionID:subID,Metric:metric,Quantity:in.Quantity,IdempotencyKey:key,OccurredAt:at};if err:=tx.Table("usage_events").Create(&ev).Error;err!=nil{return err};var usedBefore int64;if err:=tx.Table("usage_events").Where("user_id = ? AND subscription_id = ? AND metric = ? AND occurred_at >= ? AND occurred_at < ? AND id <> ?",uid,subID,metric,sub.CurrentPeriodStart,sub.CurrentPeriodEnd,ev.ID).Select("COALESCE(SUM(quantity),0)").Scan(&usedBefore).Error;err!=nil{return err};usedAfter:=usedBefore+ev.Quantity;if usedAfter<usedBefore{return errors.New("usage total overflow")};beforeOver,_,ok:=calculateOverage(usedBefore,allowance.IncludedQuantity,allowance.OverageUnitPrice);if !ok{return errors.New("usage overage overflow")};afterOver,amount,ok:=calculateOverage(usedAfter,allowance.IncludedQuantity,allowance.OverageUnitPrice);if !ok{return errors.New("usage overage overflow")};incremental:=afterOver-beforeOver;if incremental<0{return errors.New("invalid overage calculation")};if incremental>0{overAmount:=amount;if beforeOver>0{oldAmount:=beforeOver*allowance.OverageUnitPrice;if oldAmount>overAmount{return errors.New("invalid overage amount")};overAmount-=oldAmount};if err:=tx.Table("usage_overages").Create(&struct{ID string `gorm:"column:id"`;UserID string `gorm:"column:user_id"`;SubscriptionID string `gorm:"column:subscription_id"`;PackageID string `gorm:"column:package_id"`;Metric string `gorm:"column:metric"`;Quantity int64 `gorm:"column:quantity"`;UnitPrice int64 `gorm:"column:unit_price"`;Amount int64 `gorm:"column:amount"`;PeriodStart time.Time `gorm:"column:period_start"`;PeriodEnd time.Time `gorm:"column:period_end"`}{newID("ovr"),uid,subID,sub.PackageID,metric,incremental,allowance.OverageUnitPrice,overAmount,sub.CurrentPeriodStart,sub.CurrentPeriodEnd}).Error;err!=nil{return err}};c.Set("created_usage",ev);return nil});if txErr!=nil{if strings.Contains(txErr.Error(),"subscription not found"){c.JSON(404,gin.H{"error":txErr.Error()})}else if strings.Contains(txErr.Error(),"outside")||strings.Contains(txErr.Error(),"metric")||strings.Contains(txErr.Error(),"billable"){c.JSON(409,gin.H{"error":txErr.Error()})}else{c.JSON(409,gin.H{"error":"usage event could not be recorded"})};return};ev:=c.MustGet("created_usage").(UsageEvent);summaries,err:=s.calculateCurrentUsage(uid,subID);if err!=nil{c.JSON(http.StatusCreated,gin.H{"usage":ev});return};c.JSON(http.StatusCreated,gin.H{"usage":ev,"billing":summaries})})}
